#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

int main() {
    int n;
    while (std::cin >> n) {
        std::vector<std::string> v(n);
        for (int i = 0; i < n; i++) std::cin >> v[i];
        std::sort(v.begin(), v.end());
        for (int i = 0; i < n; i++) std::cout << v[i] << (i == n-1 ? "" : " ");
        std::cout << std::endl;
    }
    return 0;
}
